var body = msg.payload || {};
var telemetry = global.get('hidroTelemetryCurrent') || {};
var values = telemetry.values || {};

var commandMap = {
    bomba_principal: { start: 'comando_bomba_principal_start', stop: 'comando_bomba_principal_stop' },
    dosificador_sulfato: { start: 'comando_dosificador_sulfato_start', stop: 'comando_dosificador_sulfato_stop' },
    dosificador_cloro: { start: 'comando_dosificador_cloro_start', stop: 'comando_dosificador_cloro_stop' }
};

var target = body.target;
var command = body.command;
var operator = body.operator || 'unknown';
var source = body.source || 'api';

if (!commandMap[target] || !commandMap[target][command]) {
    msg.statusCode = 400;
    msg.payload = { accepted: false, error: 'Invalid target or command', target: target, command: command };
    return [null, msg];
}

if (values.modo_remoto_habilitado !== true) {
    msg.statusCode = 409;
    msg.payload = { accepted: false, error: 'Remote mode is not enabled', target: target, command: command };
    return [null, msg];
}

if (values.plc_en_falla === true) {
    msg.statusCode = 409;
    msg.payload = { accepted: false, error: 'PLC/process is in fault', target: target, command: command };
    return [null, msg];
}

var variable = commandMap[target][command];
var seq = (global.get('hidroCommandSequence') || 0) + 1;
global.set('hidroCommandSequence', seq);

msg.commandInfo = {
    sequence: seq,
    target: target,
    command: command,
    variable: variable,
    operator: operator,
    source: source,
    requestedAt: new Date().toISOString()
};
msg.variable = variable;
return [msg, null];

var info = msg.commandInfo || {};
var variable = info.variable;

var writeTrue = { payload: true, variable: variable };
var writeFalse = { payload: false, variable: variable };
var seqWrite = { payload: info.sequence || 0, variable: 'command_sequence' };

var response = {
    payload: {
        accepted: true,
        sequence: info.sequence,
        target: info.target,
        command: info.command,
        variable: variable,
        message: 'Comando enviado al PLC como pulso de 500 ms',
        timestamp: new Date().toISOString()
    }
};

global.set('hidroLastCommand', response.payload);
node.send([seqWrite, response]);
node.send([writeTrue, null]);
setTimeout(function () { node.send([writeFalse, null]); }, 500);
return null;
